package com.bank.courier;

import java.util.logging.Logger;

public class ObstacleRoutePlanner {

    private static final Logger log = Logger.getLogger(ObstacleRoutePlanner.class.getName());

    public int uniquePathsWithObstacles(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        if (grid[0][0] == 1 || grid[m - 1][n - 1] == 1) {
            log.warning("Start or end blocked; no path");
            return 0;                                  // cannot start or finish
        }
        int[][] dp = new int[m][n];
        dp[0][0] = 1;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {                 // obstacle contributes zero
                    dp[i][j] = 0;
                    continue;
                }
                if (i == 0 && j == 0) continue;        // already seeded
                int up = (i > 0) ? dp[i - 1][j] : 0;
                int left = (j > 0) ? dp[i][j - 1] : 0;
                dp[i][j] = up + left;                  // from above + from left
            }
        }
        int result = dp[m - 1][n - 1];
        log.info(() -> "uniquePathsWithObstacles = " + result);
        return result;
    }
}
