package com.bank.courier;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class UniquePathsIIDemo {

    private static final Logger log = Logger.getLogger(UniquePathsIIDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Obstacle Route Planner (Unique Paths II)");
        ObstacleRoutePlanner planner = new ObstacleRoutePlanner();
        int[][] grid = {{0, 0, 0}, {0, 1, 0}, {0, 0, 0}};
        log.info("3x3 with center block → " + planner.uniquePathsWithObstacles(grid)); // 2
        int[][] blocked = {{0, 1}, {0, 0}};
        log.info("2x2 with block → " + planner.uniquePathsWithObstacles(blocked));      // 1
    }
}
